import {HOMES,CATEGORIES,AMOUNTS,TYPES,UNITS,quantityOf,today,empty,item,stock,status,move,receiptLines,matches,validateBackup} from './model.mjs';
import * as storage from './storage.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=empty(),home='Tampere',view='inventory',category='All',query='',sort='name',ready=false,receipt=[],photoURL='',installEvent=null,ocrBusy=false,backup=null;
const channel='BroadcastChannel' in window?new BroadcastChannel('pantry-challenge'):null;
const icons={Fridge:'◒',Freezer:'❄',Cupboard:'▤',Household:'⌂',Toiletries:'◈',Supplements:'◉',Medicines:'✚'};
const options=(values,selected)=>values.map(x=>`<option ${x===selected?'selected':''} value="${esc(x)}">${esc(x||'Not tracked')}</option>`).join('');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function error(e){toast(e.message||String(e));}
async function save(fn,message='Saved on this device'){
 if(!ready)throw Error('Storage is unavailable.');
 try{state=await storage.change(fn);channel?.postMessage('changed');render();if(message)toast(message);return true;}catch(e){error(Error('Could not save. Your change was not applied. '+e.message));return false;}
}
function render(){
 const focus=document.activeElement?.id,position=document.activeElement?.selectionStart;
 const count=state.items.filter(x=>x.home===home).length;
 $('#app').innerHTML=`<header><div class="brand"><img src="./icon.svg" alt=""><span>Pantry Challenge</span></div><span class="sync">${navigator.onLine?'On your device':'Offline · on your device'}</span></header><div class="layout"><aside><nav aria-label="Main navigation">${[['inventory','▤','Inventory'],['useup','↘','Use It Up'],['shopping','♧','Shopping'],['receipt','▧','Receipt'],['settings','⚙','Settings']].map(([v,i,n])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span aria-hidden="true">${i}</span>${n}</button>`).join('')}</nav><div class="aside-note">A little less forgotten.<br>A little more used.<br><br>Two homes. One pantry habit.</div></aside><main>${view==='inventory'?'<button class="primary inventory-add" data-action="add">+ Add item</button>':''}<div class="homes" role="group" aria-label="Household">${HOMES.map(h=>`<button data-home="${h}" aria-pressed="${h===home}" class="${h===home?'active':''}">${h}</button>`).join('')}</div>${!ready?'<div class="error">Storage could not be opened. No changes can be saved. Try another browser or allow storage for this site. Your existing data has not been reset.</div>':view==='inventory'||view==='useup'?inventory(count):view==='shopping'?shopping():view==='receipt'?receiptPage():settings()}</main></div>`;
 if(focus&&$('#'+focus)){const el=$('#'+focus);el.focus();try{el.setSelectionRange(position,position);}catch{}}
}
function inventory(count){
 if(view==='inventory')return tileInventory();
 const use=view==='useup';let items=state.items.filter(x=>x.home===home&&(!use||x.useUp)&&(category==='All'||(category==='Check soon'?status(x).attention:x.category===category))&&matches(x.name+' '+x.notes,query));
 items.sort((a,b)=>sort==='oldest'?a.added.localeCompare(b.added):sort==='category'?a.category.localeCompare(b.category)||a.name.localeCompare(b.name):sort==='amount'?quantityOf(a)-quantityOf(b):a.name.localeCompare(b.name));
 const neglected=state.items.filter(x=>x.home===home&&x.useUp).length;
 return `<div class="intro"><div><p class="eyebrow">${use?'Make a little room':'Your home, in stock'}</p><h1>${use?'Use It Up':'What’s in your pantry?'}</h1><p class="muted">${use?'The things you’ve been meaning to get through.':'Know what you have. Use what you own.'}</p></div><button class="primary" data-action="add">+ Add item</button></div><div class="hero"><div><p class="eyebrow">${use?'A smaller backlog':'A little cupboard clarity'}</p><strong>${use?neglected+' remaining':count+' products'}</strong><p>${use?'No points or streaks. Just less neglected stuff. Remove the tag whenever your plans change.':`In ${home}. Opened, unopened, and the almost-finished bits.`}</p></div><div class="art" aria-hidden="true">${use?'↘':'▥'}</div></div><div class="toolbar"><div class="search"><input id="search" aria-label="Search inventory" placeholder="Search products, spices, notes…" value="${esc(query)}"></div><button data-action="check" aria-pressed="${category==='Check soon'}">Check soon</button></div><div class="filters" role="group" aria-label="Categories">${['All',...CATEGORIES].map(c=>`<button data-category="${c}" aria-pressed="${category===c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div><div class="list-head"><span>${items.length} ${items.length===1?'product':'products'}${category==='Check soon'?' to check':''}</span><label for="sort" class="sr">Sort <select id="sort">${options(['name','oldest','category','amount'],sort)}</select></label></div><div class="cards">${items.length?items.map(card).join(''):`<div class="empty"><div class="big" aria-hidden="true">${use?'↘':'▤'}</div><h2>${query||category!=='All'?'Nothing matches yet':use?'Nothing neglected here':'A fresh start for your pantry'}</h2><p>${use?'Flag a product as Use It Up when you want to stop overlooking it.':'Add your first product. Rough amounts are absolutely fine; no need to count every teaspoon.'}</p><button data-action="add">+ Add a product</button></div>`}</div><p class="help">${use?'Use It Up is your choice, separate from freshness reminders.':'Dates are optional. Default check reminders: fridge 7 days, freezer 3 months, cupboard 6 months. These are prompts to check, not expiry or safety advice.'}</p>`;
}
function categoryProducts(){return state.items.filter(x=>x.home===home&&x.category===category&&matches(x.name+' '+x.notes,query)).sort((a,b)=>a.name.localeCompare(b.name));}
function simpleRows(items){return items.length?`<ul class="product-list">${items.map(x=>`<li><button data-edit="${x.id}" class="product-row"><span class="product-name">${esc(x.name)}</span><span class="product-amount">${esc(stock(x))}</span><span class="product-chevron" aria-hidden="true">›</span></button></li>`).join('')}</ul>`:`<div class="category-empty"><p>${query?'No matching products.':'Nothing here yet.'}</p>${query?'':'<button data-action="add">+ Add item</button>'}</div>`;}
function tileInventory(){
 if(category==='All')return `<h1 class="pantry-title">Your inventory</h1><div class="category-grid" aria-label="Inventory categories">${['Fridge','Cupboard','Freezer','Household','Toiletries','Medicines','Supplements'].map(c=>{const n=state.items.filter(x=>x.home===home&&x.category===c).length;return `<button class="category-tile" data-category="${c}" aria-label="${c}, ${n} ${n===1?'product':'products'}"><span class="tile-icon" aria-hidden="true">${icons[c]}</span><strong>${c}</strong><span>${n} ${n===1?'product':'products'}</span></button>`;}).join('')}</div>`;
 const items=categoryProducts();return `<button class="category-back" data-category="All">‹ All categories</button><div class="category-heading"><h1>${category}</h1><span id="category-count">${items.length} ${items.length===1?'product':'products'}</span></div><div class="search category-search"><input id="category-search" type="search" aria-label="Search ${category.toLowerCase()}" placeholder="Find a product…" value="${esc(query)}"></div><div class="product-columns" aria-hidden="true"><span>Product</span><span>Amount left</span></div><div id="category-products">${simpleRows(items)}</div><p class="fine">Tap a product to change its amount or details.</p>`;
}
function card(x){const st=status(x);return `<article class="card"><div class="glyph" aria-hidden="true">${icons[x.category]}</div><div class="body"><h3><button class="title-button" data-edit="${x.id}">${esc(x.name)}</button></h3><p>${esc(stock(x))}</p><span class="tag">${x.category}</span> ${x.useUp?'<span class="tag">Use It Up</span>':''} ${st.attention||x.date?`<span class="tag ${st.attention?'amber':''}">${esc(st.label)}</span>`:''}</div><div class="card-actions"><button class="small" data-shop="${x.id}" aria-label="Add ${esc(x.name)} to shopping list">+ List</button><button class="small" data-edit="${x.id}">Edit</button></div></article>`;}
function shopping(){const list=state.shopping.filter(x=>x.home===home);return `<div class="intro"><div><p class="eyebrow">Buy with a little more certainty</p><h1>Shopping list</h1><p class="muted">Check both homes before buying another.</p></div></div><form id="shop-add" class="toolbar"><div class="search"><input id="shop-name" name="name" required maxlength="160" placeholder="What do you need?" aria-label="Product to buy" value="${esc(query)}"></div><button class="primary">+ Add</button></form><div id="stock-matches">${query?`<div class="panel"><h2>Already at home</h2>${searchStock(query)}</div>`:''}</div><div class="list-head"><span>${list.filter(x=>!x.done).length} still to buy · ${home}</span></div><div class="cards">${list.length?list.sort((a,b)=>a.done-b.done).map(x=>`<article class="card"><label class="check"><input type="checkbox" data-toggle-shop="${x.id}" ${x.done?'checked':''} aria-label="Mark ${esc(x.name)} ${x.done?'needed':'bought'}"></label><div class="body ${x.done?'done':''}"><h3>${esc(x.name)}</h3><p>${esc(x.note)}</p><div class="shop-stock">${searchStock(x.name)}</div></div><button class="small" data-remove-shop="${x.id}" aria-label="Remove ${esc(x.name)}">×</button></article>`).join(''):'<div class="empty"><h2>A considered little shopping list</h2><p>Add anything you need, including products you don’t track in your pantry.</p></div>'}</div><p class="help">Checking “bought” only updates this list. Add purchases to stock yourself or review a receipt.</p>`;}
function searchStock(q){let xs=state.items.filter(x=>matches(x.name,q));return xs.length?xs.map(x=>`<p><strong>${esc(x.name)}</strong> · ${x.home}<br>${esc(stock(x))}</p>`).join(''):'<p class="muted">No matching stock in either home.</p>';}
function receiptPage(){return `<div class="intro"><div><p class="eyebrow">From shop to shelf</p><h1>Bring in a receipt</h1><p class="muted">A photo, a quick review, then into your pantry.</p></div></div><div class="panel"><h2>1. Choose a receipt photo</h2><p>Text recognition runs on this device. Photos are never uploaded or saved. Finnish and English are supported.</p><label for="photo">Receipt photo</label><input id="photo" type="file" accept="image/*" ${ocrBusy?'disabled':''}><label for="language">Receipt language</label><select id="language">${options(['Finnish','English'],'Finnish')}</select><div id="ocr-status" class="progress" role="status">${ocrBusy?'Reading your receipt…':''}</div><div id="photo-preview"></div><label for="receipt-text">2. Check the text or paste a receipt</label><textarea id="receipt-text" placeholder="Milk 1.49&#10;2 x Oregano 2.98"></textarea><p class="fine">OCR can miss lines or misread names and quantities. Remove shop details and payment lines. You can also enter one product per line.</p><button data-action="parse" ${ocrBusy?'disabled':''}>Review items →</button></div><div id="receipt-review">${receiptReview()}</div>`;}
function receiptReview(){return receipt.length?`<div class="panel"><h2>3. Review every item</h2><p>Nothing is saved yet. Correct names, quantities, units and destinations. Untick anything that isn’t a product. Every checked row must be marked reviewed.</p><form id="receipt-commit">${receipt.map((x,i)=>`<fieldset class="receipt-row" data-receipt="${i}"><legend>Item ${i+1}</legend><label class="check"><input type="checkbox" name="include" checked> Include this item</label>${typeSelector({...x,tracking:x.tracking||'count'})}<label>Product name<input name="name" required maxlength="160" value="${esc(x.name)}"></label><div class="row"><label>Home<select name="home">${options(HOMES,x.home)}</select></label><label>Category<select name="category">${options(CATEGORIES,x.category)}</select></label></div>${stockFields({...x,tracking:x.tracking||'count',quantity:x.quantity??x.unopened})}<label>Date (optional)<input type="date" name="date"></label><label>Date type<select name="dateKind">${options(['Reminder','Best before','Use by'],'Reminder')}</select></label><label class="check"><input type="checkbox" name="reviewed"> I’ve checked this item</label></fieldset>`).join('')}<p class="fine">Products with the same name stay separate so their opened quantities and dates are preserved.</p><div id="receipt-error" role="alert"></div><button class="primary">Save reviewed items</button></form></div>`:'';}
function settings(){return `<div class="intro"><div><p class="eyebrow">Keep it yours</p><h1>Your pantry, safely kept</h1><p class="muted">Stored in this browser on this device.</p></div></div><div class="panel"><h2>Backup & restore</h2><p>Export regularly and before changing browser or device. A backup includes both homes and the shopping lists. Browser data can be cleared by your device; it does not sync automatically.</p><div class="settings-grid"><button data-action="export">↓ Export backup</button><label for="backup-file">Choose a backup to review</label><input id="backup-file" type="file" accept=".json,application/json"><button data-action="undo">Undo last saved change</button><button data-action="persist">Ask this browser to keep storage</button></div><div id="persistence" class="fine"></div></div><div class="panel"><h2>Install & offline</h2><p id="offline-status">${offlineStatus}</p><button data-action="install">Install Pantry Challenge</button><p class="fine">On iPhone: open in Safari, tap Share, then Add to Home Screen. On Android or desktop: use Install in your browser menu. Open the app once online and wait for the offline-ready message.</p></div><div class="panel"><h2>Private by design</h2><p>No analytics, account password, advertising or cloud inventory. Receipt photos are processed locally and discarded when you leave. Backups are plain JSON files; store them somewhere private. Anyone with access to your unlocked browser can see your inventory.</p><p class="fine">Date defaults are check reminders only. Household, toiletries, supplements and medicines have no automatic date reminder. “Finish / remove” removes a product row; it does not infer how you used it.</p></div>`;}
let offlineStatus='Preparing the offline app…';
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();}
function typeSelector(x){return `<label>Item type<select name="tracking" data-tracking>${TYPES.map(t=>`<option value="${t.id}" ${t.id===(x.tracking==='containers'?'partial':x.tracking)?'selected':''}>${t.label}</option>`).join('')}</select></label>`;}
function unitSelector(unit,name='unit',label='Unit'){
 const custom=!UNITS.includes(unit);
 return `<div data-unit-control><label>${label}<select name="${name}" data-unit-select>${options(UNITS,custom?'':unit)}<option value="__custom__" ${custom?'selected':''}>Custom…</option></select></label><label data-custom-unit ${custom?'':'hidden'}>Custom unit<input name="${name}Custom" maxlength="40" value="${custom?esc(unit):''}" ${custom?'required':'disabled'} placeholder="Your unit"></label></div>`;
}
function stockFields(x){const split=x.tracking==='containers',partial=x.tracking!=='count';return `<fieldset data-stock-fields><legend>What’s left</legend>${partial?`<label class="check"><input name="split" data-split type="checkbox" ${split?'checked':''}> Track opened / unopened separately (optional)</label>`:''}${!split?`<label>Quantity<input name="quantity" type="number" min="0" max="1000000" step="${partial?'any':'1'}" required value="${x.quantity}"></label><p class="fine">${partial?'Partial amounts are fine: 2.5 cartons of milk or 1.5 bags of grated cheese.':'Whole items only: 12 eggs or 6 cans of soda.'}</p>`:`<div class="row"><label>Unopened<input name="unopened" type="number" min="0" max="1000000" step="any" required value="${x.unopened}"></label><label>Opened remaining<input name="opened" type="number" min="0" max="1000000" step="any" required value="${x.opened}"></label></div><label>Rough amount remaining in opened stock<select name="amount">${options(AMOUNTS,x.amount)}</select></label><p class="fine">For 2.5 cartons: 2 unopened + 0.5 opened remaining. Edit these independently; moving stock never opens it.</p>`}${unitSelector(x.unit)}</fieldset>`;}
function stockValues(scope){const v=n=>scope.querySelector(`[name="${n}"]`)?.value;const selected=v('tracking')||'partial',tracking=selected==='partial'&&scope.querySelector('[name=split]')?.checked?'containers':selected;return {tracking,quantity:tracking!=='containers'?Number(v('quantity')):0,unopened:tracking==='containers'?Number(v('unopened')):0,opened:tracking==='containers'?Number(v('opened')):0,amount:tracking==='containers'?(v('amount')||''):'',unit:(v('unit')==='__custom__'?v('unitCustom'):v('unit'))?.trim()||''};}
function edit(id){const x=id?state.items.find(x=>x.id===id):{name:'',home,category:CATEGORIES.includes(category)?category:'Cupboard',tracking:'count',quantity:1,unit:'pieces',unopened:0,opened:0,amount:'',date:'',dateKind:'Reminder',useUp:false,notes:''};if(!x)return;
 modal(`<form id="item-form" data-id="${id||''}"><h2>${id?'Edit product':'A new pantry addition'}</h2>${typeSelector(x)}<label>Product name<input name="name" maxlength="160" required value="${esc(x.name)}" placeholder="e.g. Eggs"></label><div class="row"><label>Home<select name="home">${options(HOMES,x.home)}</select></label><label>Category<select name="category">${options(CATEGORIES,x.category)}</select></label></div>${stockFields(x)}<div class="row"><label>Date (optional)<input name="date" type="date" value="${x.date}"></label><label>Date type<select name="dateKind">${options(['Reminder','Best before','Use by'],x.dateKind)}</select></label></div><label class="check"><input name="useUp" type="checkbox" ${x.useUp?'checked':''}> Use It Up — I’ve been neglecting this</label><label>Notes<textarea name="notes" maxlength="2000" placeholder="Anything useful to remember">${esc(x.notes)}</textarea></label><div id="item-error" role="alert"></div><div class="actions">${id?`<button type="button" data-move="${id}">Move stock</button><button type="button" class="danger" data-delete="${id}">Finish / remove</button>`:''}<button type="button" data-action="close">Cancel</button><button class="primary">Save product</button></div></form>`);
}
function readForm(form){const f=new FormData(form);return {name:String(f.get('name')).trim(),home:f.get('home'),category:f.get('category'),...stockValues(form),date:f.get('date')||'',dateKind:f.get('dateKind')||'Reminder',useUp:f.has('useUp'),notes:f.get('notes')||''};}
function changeTracking(select){const scope=select.closest('#item-form,[data-receipt]');refreshStockFields(scope,select.value);}
function refreshStockFields(scope,tracking){const q=scope.querySelector('[name=quantity]');const total=q?Number(q.value):Number(scope.querySelector('[name=unopened]').value)+Number(scope.querySelector('[name=opened]').value);
 const unitSelect=scope.querySelector('[name=unit]');const unit=unitSelect.value==='__custom__'?scope.querySelector('[name=unitCustom]').value:unitSelect.value;
 scope.querySelector('[data-stock-fields]').outerHTML=stockFields({tracking,quantity:total,unopened:total,opened:0,amount:'',unit});
 if(tracking==='count'&&!Number.isInteger(total))toast('Whole items need a whole-number count. Please adjust the quantity.');
}
async function addShop(id){const x=state.items.find(x=>x.id===id);if(!x)return;await save(s=>{if(!s.shopping.some(y=>y.home===home&&!y.done&&y.name.toLocaleLowerCase()===x.name.toLocaleLowerCase()))s.shopping.push({id:crypto.randomUUID(),home,name:x.name,note:'',done:false});return s;},'Added to shopping list');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(ocrBusy&&(b.dataset.view||b.dataset.home)){toast('Wait for receipt reading to finish first.');return;}try{
 if(b.dataset.view){view=b.dataset.view;query='';category='All';if(view!=='receipt'&&!ocrBusy){receipt=[];if(photoURL)URL.revokeObjectURL(photoURL);photoURL='';}render();}
 else if(b.dataset.home){home=b.dataset.home;render();}
 else if(b.dataset.category){category=b.dataset.category;query='';render();}
 else if(b.dataset.edit)edit(b.dataset.edit);
 else if(b.dataset.shop)await addShop(b.dataset.shop);
 else if(b.dataset.removeShop)await save(s=>({...s,shopping:s.shopping.filter(x=>x.id!==b.dataset.removeShop)}),'Removed from list');
 else if(b.dataset.delete){const id=b.dataset.delete,x=state.items.find(x=>x.id===id);modal(`<h2>Finish ${esc(x.name)}?</h2><p>This removes the whole product row and its remaining stock. To reduce only part of it, cancel and edit the quantities.</p><div class="actions"><button data-action="close">Cancel</button><button class="danger" data-confirm-delete="${id}">Remove product</button></div>`);}
 else if(b.dataset.confirmDelete){if(await save(s=>({...s,items:s.items.filter(x=>x.id!==b.dataset.confirmDelete)}),'Product removed. You can undo in Settings.'))$('#modal').close();}
 else if(b.dataset.move){const x=state.items.find(x=>x.id===b.dataset.move);modal(`<form id="move-form" data-id="${x.id}"><h2>Move ${esc(x.name)}</h2><p>${esc(stock(x))}</p><label>Destination home<select name="home">${options(HOMES,x.home)}</select></label><label>Destination category<select name="category">${options(CATEGORIES,x.category)}</select></label><p class="fine">Moves this whole row. The quantity and tracking type stay exactly as they are. For a partial move, adjust this row and add the moved stock separately.</p><div class="actions"><button type="button" data-action="close">Cancel</button><button class="primary">Move stock</button></div></form>`);}
 else switch(b.dataset.action){
 case 'add':edit();break;
 case 'close':$('#modal').close();break;
 case 'check':category=category==='Check soon'?'All':'Check soon';render();break;
 case 'export':{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}));a.href=url;a.download=`pantry-challenge-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported');break;}
 case 'undo':{const old=await storage.previous();if(!old){toast('No previous change to undo');break;}modal(`<h2>Undo the last change?</h2><p>Restore ${old.items.length} products and ${old.shopping.length} shopping entries across both homes. This restores the state before the most recent saved change.</p><div class="actions"><button data-action="close">Cancel</button><button class="primary" data-action="confirm-undo">Restore previous state</button></div>`);break;}
 case 'confirm-undo':{const old=await storage.previous();if(old&&await save(()=>old,'Last change undone'))$('#modal').close();break;}
 case 'persist':{const granted=await navigator.storage?.persist?.();$('#persistence').textContent=granted?'Persistent storage granted. Keep exporting backups too.':'This browser did not grant persistent storage. Regular exports are recommended.';break;}
 case 'install':if(installEvent){await installEvent.prompt();installEvent=null;}else toast('Use your browser menu to install, or Share → Add to Home Screen in Safari.');break;
 case 'parse':{const raw=$('#receipt-text').value.trim();if(!raw){toast('Choose a photo or enter some receipt text first');break;}receipt=receiptLines(raw,home);$('#receipt-review').innerHTML=receiptReview();if(!receipt.length)toast('No product lines found. Try entering one product per line.');else $('#receipt-review').scrollIntoView({behavior:'smooth'});break;}
 case 'import':if(backup&&await save(()=>backup,'Backup restored across both homes')){$('#modal').close();backup=null;}break;
 }
 }catch(err){error(err);}});
document.addEventListener('input',e=>{if(e.target.id==='category-search'){query=e.target.value;const items=categoryProducts();$('#category-products').innerHTML=simpleRows(items);$('#category-count').textContent=items.length+' '+(items.length===1?'product':'products');}if(e.target.id==='search'){query=e.target.value;render();}if(e.target.id==='shop-name'){query=e.target.value;$('#stock-matches').innerHTML=query?`<div class="panel"><h2>Already at home</h2>${searchStock(query)}</div>`:'';}});
document.addEventListener('change',async e=>{try{if(e.target.matches('[data-tracking]'))changeTracking(e.target);if(e.target.matches('[data-split]'))refreshStockFields(e.target.closest('#item-form,[data-receipt]'),e.target.checked?'containers':'partial');if(e.target.matches('[data-unit-select]')){const scope=e.target.closest('[data-unit-control]');const custom=scope.querySelector('[data-custom-unit]');custom.hidden=e.target.value!=='__custom__';const input=custom.querySelector('input');input.disabled=custom.hidden;input.required=!custom.hidden;if(!custom.hidden)input.focus();}if(e.target.name==='include'){for(const input of e.target.closest('fieldset').querySelectorAll('input,select'))if(input!==e.target)input.disabled=!e.target.checked;}if(e.target.id==='sort'){sort=e.target.value;render();}if(e.target.dataset.toggleShop)await save(s=>({...s,shopping:s.shopping.map(x=>x.id===e.target.dataset.toggleShop?{...x,done:e.target.checked}:x)}),'List updated');if(e.target.id==='photo')await readPhoto(e.target.files[0]);if(e.target.id==='backup-file'){const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Backup must be under 10 MB.');backup=validateBackup(JSON.parse(await file.text()));modal(`<h2>Restore this backup?</h2><p>${backup.items.length} products and ${backup.shopping.length} shopping entries.</p>${HOMES.map(h=>`<p>${h}: ${backup.items.filter(x=>x.home===h).length} products</p>`).join('')}<p>This replaces both inventories and both shopping lists on this device. Export your current data first if you want to keep it.</p><div class="actions"><button data-action="close">Cancel</button><button class="primary" data-action="import">Replace with backup</button></div>`);}}catch(err){error(err);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;try{if(f.id==='item-form'){const id=f.dataset.id,data=readForm(f),old=state.items.find(x=>x.id===id);const x=item({...old,...data,...(id?{id}:{} )});if(await save(s=>{if(id){if(!s.items.some(y=>y.id===id))throw Error('This product was removed in another tab.');s.items=s.items.map(y=>y.id===id?x:y);}else s.items.push(x);return s;}))$('#modal').close();}
 if(f.id==='move-form'){const d=new FormData(f);if(await save(s=>move(s,f.dataset.id,d.get('home'),d.get('category')),'Stock moved; quantities unchanged'))$('#modal').close();}
 if(f.id==='shop-add'){const name=new FormData(f).get('name').trim();if(!name)return;query='';await save(s=>{if(!s.shopping.some(x=>x.home===home&&!x.done&&x.name.toLowerCase()===name.toLowerCase()))s.shopping.push({id:crypto.randomUUID(),name,home,note:'',done:false});return s;},'Added to shopping list');}
 if(f.id==='receipt-commit'){const rows=[...f.querySelectorAll('[data-receipt]')].filter(r=>r.querySelector('[name=include]').checked);if(!rows.length)throw Error('Select at least one item.');if(rows.some(r=>!r.querySelector('[name=reviewed]').checked))throw Error('Check and mark every included item as reviewed first.');const batch=rows.map(r=>{const v=n=>r.querySelector(`[name=${n}]`).value;return item({name:v('name').trim(),home:v('home'),category:v('category'),...stockValues(r),date:v('date'),dateKind:v('dateKind')});});if(await save(s=>({...s,items:[...s.items,...batch]}),`${batch.length} reviewed products saved`)){receipt=[];view='inventory';render();}}
 }catch(err){const el=f.querySelector('[role=alert]')||$('#receipt-error');if(el){el.className='error';el.textContent=err.message;}else error(err);}});
async function readPhoto(file){if(!file)return;if(file.size>20*1024*1024){toast('Choose a photo under 20 MB.');return;}if(!file.type.startsWith('image/')){toast('Choose an image file.');return;}ocrBusy=true;let worker;const language=$('#language').value==='Finnish'?'fin':'eng';if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(file);const preview=$('#photo-preview');const img=document.createElement('img');img.className='receipt-preview';img.alt='Your receipt for checking';img.src=photoURL;preview.replaceChildren(img);const progress=$('#ocr-status');const photo=$('#photo');photo.disabled=true;$('[data-action=parse]').disabled=true;try{if(!window.Tesseract)throw Error('Receipt reader is unavailable. Wait for offline setup or paste the receipt text.');worker=await Tesseract.createWorker(language,1,{workerPath:new URL('./vendor/worker.min.js',location.href).href,corePath:new URL('./vendor/tesseract-core.wasm.js',location.href).href,langPath:new URL('./vendor/',location.href).href,workerBlobURL:false,logger:m=>{if(progress.isConnected)progress.textContent=m.status+(m.progress?' '+Math.round(m.progress*100)+'%':'');}});const result=await worker.recognize(file);if($('#receipt-text')){$('#receipt-text').value=result.data.text;progress.textContent='Text ready. Check it, then review the products below.';}}catch(e){progress.textContent='Could not read this photo. Try a clearer JPEG/PNG or paste the receipt text.';}finally{await worker?.terminate();ocrBusy=false;if(photo.isConnected)photo.disabled=false;if($('[data-action=parse]'))$('[data-action=parse]').disabled=false;}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
const connectionChanged=()=>{const el=$('.sync');if(el)el.textContent=navigator.onLine?'On your device':'Offline · on your device';};window.addEventListener('online',connectionChanged);window.addEventListener('offline',connectionChanged);
channel?.addEventListener('message',async()=>{state=await storage.read();render();});
try{await storage.connect();state=await storage.read();ready=true;}catch(e){console.error(e);}render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async reg=>{const check=()=>{offlineStatus='Offline app ready, including receipt reading. Open this installed app from this same browser.';if(view==='settings')render();};if(reg.active)check();reg.addEventListener('updatefound',()=>{const w=reg.installing;w.addEventListener('statechange',()=>{if(w.state==='activated'){check();toast('Pantry ready to use offline');}});});await navigator.serviceWorker.ready;check();}).catch(()=>{offlineStatus='Offline setup failed. Reopen online to retry. Inventory is still saved on this device.';if(view==='settings')render();});}
